# Re-apply Claude Code sidebar fix after extension updates.
# Run: powershell -ExecutionPolicy Bypass -File "$env:APPDATA\Cursor\User\fix-claude-sidebar.ps1"

$extRoot = Join-Path $env:USERPROFILE ".cursor\extensions"
$pkg = Get-ChildItem -Path $extRoot -Filter "anthropic.claude-code-*" -Directory |
    Sort-Object Name -Descending |
    Select-Object -First 1

if (-not $pkg) {
    Write-Error "Claude Code extension not found under $extRoot"
    exit 1
}

$js = Join-Path $pkg.FullName "extension.js"
$pkgJson = Join-Path $pkg.FullName "package.json"
$content = Get-Content $js -Raw
$changed = $false

$patch1Old = 'let q=_0.version.split(".").map(Number),U=q[0]??0,M=q[1]??0,G=U>1||U===1&&M>=106;if(!G)_0.commands.executeCommand("setContext","claude-code:doesNotSupportSecondarySidebar",!0);'
$patch1New = 'let q=_0.version.split(".").map(Number),U=q[0]??0,M=q[1]??0,G=U>1||U===1&&M>=106;_0.commands.executeCommand("setContext","claude-code:doesNotSupportSecondarySidebar",!0);'

$patch2Old = 'N.getPreferredLocation()==="sidebar"&&G)F.show();if(z.subscriptions.push(_0.commands.registerCommand("claude-vscode.sidebar.open",async()=>{if(N.setPreferredLocation("sidebar"),!G){_0.window.showWarningMessage("Secondary Sidebar not supported in this version of VSCode. Please update your VSCode to use. Opening in Activity Bar instead."),await _0.commands.executeCommand("claudeVSCodeSidebar.focus");return}await _0.commands.executeCommand("claudeVSCodeSidebarSecondary.focus"),F.show()}))'
$patch2New = 'N.getPreferredLocation()==="sidebar")F.show();if(z.subscriptions.push(_0.commands.registerCommand("claude-vscode.sidebar.open",async()=>{N.setPreferredLocation("sidebar"),await _0.commands.executeCommand("claudeVSCodeSidebar.focus"),F&&F.show()}))'

foreach ($pair in @(
    @{ Old = $patch1Old; New = $patch1New; Name = "context" },
    @{ Old = $patch2Old; New = $patch2New; Name = "sidebar.open" }
)) {
    if ($content.Contains($pair.New)) {
        Write-Host "Patch $($pair.Name) already applied"
    }
    elseif ($content.Contains($pair.Old)) {
        $content = $content.Replace($pair.Old, $pair.New)
        $changed = $true
        Write-Host "Applied patch: $($pair.Name)"
    }
    else {
        Write-Warning "Patch $($pair.Name) pattern not found; extension may have changed."
    }
}

if ($changed) {
    Set-Content -Path $js -Value $content -NoNewline
}

# package.json: force primary sidebar only
if (Test-Path $pkgJson) {
    $json = Get-Content $pkgJson -Raw
    $jsonNew = $json
    $jsonNew = $jsonNew -replace '"when": "claude-code:doesNotSupportSecondarySidebar"\r?\n\s*', ''
    $jsonNew = $jsonNew -replace '"claude-sidebar-secondary": \[\s*\{\s*"type": "webview",\s*"id": "claudeVSCodeSidebarSecondary",\s*"name": "Claude Code",\s*"when": "!claude-code:doesNotSupportSecondarySidebar"\s*\}\s*\],?\s*', ''
    $jsonNew = $jsonNew -replace '"secondarySidebar": \[\s*\{\s*"id": "claude-sidebar-secondary"[\s\S]*?\}\s*\]', '"secondarySidebar": []'
    if ($jsonNew -ne $json) {
        Set-Content -Path $pkgJson -Value $jsonNew -NoNewline
        Write-Host "Updated package.json"
    }
}

Write-Host "Done: $($pkg.Name)"
Write-Host "Reload Cursor: Ctrl+Shift+P -> Developer: Reload Window"

# Sync current CC Switch providers -> Claude CLI + Cursor Claude Code extension + Codex
param(
    [string]$ClaudeProviderId,
    [string]$CodexProviderId
)

$dbPath = Join-Path $env:USERPROFILE ".cc-switch\cc-switch.db"
$ccSettingsPath = Join-Path $env:USERPROFILE ".cc-switch\settings.json"
$claudeSettingsPath = Join-Path $env:USERPROFILE ".claude\settings.json"
$cursorSettingsPath = Join-Path $env:APPDATA "Cursor\User\settings.json"
$codexConfigPath = Join-Path $env:USERPROFILE ".codex\config.toml"
$codexAuthPath = Join-Path $env:USERPROFILE ".codex\auth.json"

function Get-ProviderConfig {
    param([string]$Id)
    $py = Join-Path $env:TEMP "cc-sync-get-provider.py"
    @"
import sqlite3, json, os, sys
c = sqlite3.connect(r"$($dbPath.Replace('\','\\'))")
row = c.execute("SELECT name, app_type, settings_config FROM providers WHERE id=?", (sys.argv[1],)).fetchone()
if not row:
    sys.exit(2)
print(json.dumps({"name": row[0], "app_type": row[1], "settings_config": json.loads(row[2])}))
"@ | Set-Content -Encoding utf8 $py
    $out = python $py $Id 2>$null
    Remove-Item $py -ErrorAction SilentlyContinue
    if (-not $out) { return $null }
    return $out | ConvertFrom-Json
}

function Merge-ClaudeSettings {
    param($ProviderConfig, [hashtable]$Preserve)
    $cfg = $ProviderConfig.settings_config
  if (-not $cfg.env) { $cfg.env = @{} }
    $merged = @{}
    if (Test-Path $claudeSettingsPath) {
        $existing = Get-Content $claudeSettingsPath -Raw | ConvertFrom-Json
        $existing.PSObject.Properties | ForEach-Object {
            if ($_.Name -ne 'env') { $merged[$_.Name] = $_.Value }
        }
        if ($existing.env) {
            $existing.env.PSObject.Properties | ForEach-Object { $merged["env:$($_.Name)"] = $_.Value }
        }
    }
    foreach ($k in $Preserve.Keys) { $merged[$k] = $Preserve[$k] }
    foreach ($p in $cfg.PSObject.Properties) {
        if ($p.Name -eq 'env') {
            foreach ($e in $p.Value.PSObject.Properties) {
                $merged["env:$($e.Name)"] = $e.Value
            }
        } else {
            $merged[$p.Name] = $p.Value
        }
    }
    $out = [ordered]@{}
    foreach ($key in ($merged.Keys | Sort-Object)) {
        if ($key -like 'env:*') { continue }
        $out[$key] = $merged[$key]
    }
    $envOut = [ordered]@{}
    foreach ($key in ($merged.Keys | Where-Object { $_ -like 'env:*' } | Sort-Object)) {
        $envOut[($key -replace '^env:','')] = $merged[$key]
    }
    if ($envOut.Count -gt 0) { $out['env'] = $envOut }
    return ($out | ConvertTo-Json -Depth 20)
}

function Set-CursorClaudeEnv {
    param($EnvObj)
    if (-not (Test-Path $cursorSettingsPath)) { return }
    $cursor = Get-Content $cursorSettingsPath -Raw | ConvertFrom-Json
    $vars = @()
    foreach ($p in $EnvObj.PSObject.Properties) {
        if ($p.Value) {
            $vars += [ordered]@{ name = $p.Name; value = [string]$p.Value }
        }
    }
    $cursor | Add-Member -NotePropertyName 'claudeCode.environmentVariables' -NotePropertyValue $vars -Force
    $cursor | ConvertTo-Json -Depth 10 | Set-Content -Path $cursorSettingsPath -Encoding utf8
}

function Apply-CodexProvider {
    param($ProviderConfig)
    $sc = $ProviderConfig.settings_config
    if ($sc.config) {
        Set-Content -Path $codexConfigPath -Value $sc.config -Encoding utf8
    }
    if ($sc.auth) {
        $auth = if (Test-Path $codexAuthPath) { Get-Content $codexAuthPath -Raw | ConvertFrom-Json } else { [ordered]@{} }
        foreach ($p in $sc.auth.PSObject.Properties) {
            $auth | Add-Member -NotePropertyName $p.Name -NotePropertyValue $p.Value -Force
        }
        $auth | ConvertTo-Json -Depth 5 | Set-Content -Path $codexAuthPath -Encoding utf8
    }
}

if (-not (Test-Path $dbPath)) {
    Write-Error "CC Switch database not found: $dbPath"
    exit 1
}

$cc = Get-Content $ccSettingsPath -Raw | ConvertFrom-Json
if (-not $ClaudeProviderId) { $ClaudeProviderId = $cc.currentProviderClaude }
if (-not $CodexProviderId) { $CodexProviderId = $cc.currentProviderCodex }

Write-Host "=== CC Switch full sync ===" -ForegroundColor Cyan

# Enable Cursor plugin integration in CC Switch
if ($cc.enableClaudePluginIntegration -ne $true) {
    $cc.enableClaudePluginIntegration = $true
    $cc | ConvertTo-Json -Depth 5 | Set-Content -Path $ccSettingsPath -Encoding utf8
    Write-Host "[OK] Enabled enableClaudePluginIntegration in CC Switch" -ForegroundColor Green
}

$claude = Get-ProviderConfig $ClaudeProviderId
if ($claude) {
    $preserve = @{ includeCoAuthoredBy = $false }
    if (Test-Path $claudeSettingsPath) {
        $old = Get-Content $claudeSettingsPath -Raw | ConvertFrom-Json
        if ($old.hooks) { $preserve['hooks'] = $old.hooks }
        if ($null -ne $old.includeCoAuthoredBy) { $preserve['includeCoAuthoredBy'] = $old.includeCoAuthoredBy }
    }
    $json = Merge-ClaudeSettings $claude $preserve
    Set-Content -Path $claudeSettingsPath -Value $json -Encoding utf8
    $envObj = ($json | ConvertFrom-Json).env
    if ($envObj) { Set-CursorClaudeEnv $envObj }
    Write-Host "[OK] Claude -> $($claude.name) ($ClaudeProviderId)" -ForegroundColor Green
    Write-Host "     BASE_URL: $($envObj.ANTHROPIC_BASE_URL)"
} else {
    Write-Warning "Claude provider not found: $ClaudeProviderId"
}

$codex = Get-ProviderConfig $CodexProviderId
if ($codex) {
    Apply-CodexProvider $codex
    Write-Host "[OK] Codex -> $($codex.name) ($CodexProviderId)" -ForegroundColor Green
} else {
    Write-Warning "Codex provider not found: $CodexProviderId"
}

Write-Host ""
Write-Host "Next steps:" -ForegroundColor Yellow
Write-Host "  1. Exit ALL Claude Code panels and terminal 'claude' sessions"
Write-Host "  2. Cursor: Ctrl+Shift+P -> Developer: Reload Window"
Write-Host "  3. If extension still uses OAuth: Ctrl+Shift+P -> Claude Code: Logout"
Write-Host "  4. Open new terminal, run: claude"
Write-Host ""
Write-Host "Clear stale process env (if any):" -ForegroundColor DarkGray
Write-Host '  Remove-Item Env:ANTHROPIC_BASE_URL, Env:ANTHROPIC_AUTH_TOKEN, Env:ANTHROPIC_API_KEY -EA SilentlyContinue'

