# Watch CC Switch provider changes and auto-sync Claude Code + Cursor + Codex.
# Run at login: install via install-cc-auto-sync.ps1

$ErrorActionPreference = 'SilentlyContinue'
$ccSettings = Join-Path $env:USERPROFILE '.cc-switch\settings.json'
$stateFile = Join-Path $env:USERPROFILE '.claude\scripts\.cc-watch-state.json'
$syncScript = Join-Path $env:USERPROFILE '.claude\scripts\cc-sync-all.ps1'
$logFile = Join-Path $env:USERPROFILE '.claude\scripts\cc-watch-sync.log'

function Write-Log([string]$Msg) {
    $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Msg
    Add-Content -Path $logFile -Value $line -Encoding utf8
}

function Get-ProviderIds {
    if (-not (Test-Path $ccSettings)) { return $null }
    try {
        $j = Get-Content $ccSettings -Raw -Encoding UTF8 | ConvertFrom-Json
        return @{
            Claude = [string]$j.currentProviderClaude
            Codex  = [string]$j.currentProviderCodex
        }
    } catch { return $null }
}

function Invoke-SyncIfChanged([hashtable]$Ids, [string]$Reason) {
    $prev = $null
    if (Test-Path $stateFile) {
        try { $prev = Get-Content $stateFile -Raw -Encoding UTF8 | ConvertFrom-Json } catch {}
    }
    $same = $prev -and $prev.Claude -eq $Ids.Claude -and $prev.Codex -eq $Ids.Codex
    if ($same) { return }

    Write-Log "Change detected ($Reason): Claude=$($Ids.Claude) Codex=$($Ids.Codex)"
    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $syncScript -ClaudeProviderId $Ids.Claude -CodexProviderId $Ids.Codex 2>&1 | ForEach-Object { Write-Log $_ }

    $Ids | ConvertTo-Json | Set-Content -Path $stateFile -Encoding utf8
    Write-Log 'Sync completed.'
}

# Initial sync on start
$initial = Get-ProviderIds
if ($initial) { Invoke-SyncIfChanged $initial 'startup' }

if (-not (Test-Path $ccSettings)) {
    Write-Log "Waiting for CC Switch settings: $ccSettings"
    exit 1
}

$dir = Split-Path $ccSettings -Parent
$watcher = New-Object System.IO.FileSystemWatcher $dir, 'settings.json'
$watcher.NotifyFilter = [IO.NotifyFilters]'FileName, LastWrite, Size'
$watcher.EnableRaisingEvents = $true

$debounce = $null
$onChange = {
    if ($debounce) { $debounce.Dispose() }
    $script:debounce = [System.Timers.Timer]::new(600)
    $debounce.AutoReset = $false
    $debounce.Add_Elapsed({
        $ids = Get-ProviderIds
        if ($ids) { Invoke-SyncIfChanged $ids 'cc-switch' }
    })
    $debounce.Start()
}

Register-ObjectEvent $watcher Changed -Action $onChange | Out-Null
Register-ObjectEvent $watcher Created -Action $onChange | Out-Null
Register-ObjectEvent $watcher Renamed -Action $onChange | Out-Null

Write-Log 'Watcher started.'

try {
    while ($true) { Start-Sleep -Seconds 3600 }
} finally {
    $watcher.Dispose()
}

