param(
    [int]$PollSeconds = 2
)

$ccSettings = Join-Path $env:USERPROFILE '.cc-switch\settings.json'
$stateFile = Join-Path $env:USERPROFILE '.claude\scripts\.cc-watch-state.json'
$syncScript = Join-Path $env:USERPROFILE '.claude\scripts\cc-sync-all.ps1'
$logFile = Join-Path $env:USERPROFILE '.claude\scripts\cc-watch-sync.log'

function Write-Log([string]$Msg) {
    $line = "[{0}] {1}" -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Msg
    Add-Content -Path $logFile -Value $line -Encoding utf8
}

function Get-ProviderIds {
    if (-not (Test-Path $ccSettings)) { return $null }
    try {
        $raw = [System.IO.File]::ReadAllText($ccSettings)
        $j = $raw | ConvertFrom-Json
        return @{
            Claude = [string]$j.currentProviderClaude
            Codex  = [string]$j.currentProviderCodex
        }
    } catch { return $null }
}

function Get-StateIds {
    if (-not (Test-Path $stateFile)) { return $null }
    try {
        $s = Get-Content $stateFile -Raw -Encoding UTF8 | ConvertFrom-Json
        return @{ Claude = [string]$s.Claude; Codex = [string]$s.Codex }
    } catch { return $null }
}

function Invoke-Sync([hashtable]$Ids, [string]$Reason) {
    Write-Log "Sync ($Reason): Claude=$($Ids.Claude) Codex=$($Ids.Codex)"
    & powershell.exe -NoProfile -ExecutionPolicy Bypass -File $syncScript `
        -ClaudeProviderId $Ids.Claude -CodexProviderId $Ids.Codex -Quiet 2>&1 | ForEach-Object { Write-Log $_ }
    $Ids | ConvertTo-Json | Set-Content -Path $stateFile -Encoding utf8
    Write-Log 'Done.'
}

Write-Log 'Watcher started (poll every {0}s).' -f $PollSeconds

while ($true) {
    $ids = Get-ProviderIds
    if ($ids) {
        $prev = Get-StateIds
        if (-not $prev -or $prev.Claude -ne $ids.Claude -or $prev.Codex -ne $ids.Codex) {
            Invoke-Sync $ids $(if ($prev) { 'switch' } else { 'startup' })
        }
    }
    Start-Sleep -Seconds $PollSeconds
}

